export type CustomerSegmentDefinition = {
    version?: 1;
    match?: 'all' | 'any';
    conditions: Array<{
        field: 'amount_spent';
        min?: number;
        max?: number;
    } | {
        field: 'orders_count';
        min?: number;
        max?: number;
    } | {
        field: 'last_order_date';
        filter: {
            op: 'within_last';
            days: number;
        } | {
            op: 'not_within_last';
            days: number;
        } | {
            op: 'on_or_after';
            date: string;
        } | {
            op: 'before';
            date: string;
        };
    } | {
        field: 'first_order_date';
        filter: {
            op: 'within_last';
            days: number;
        } | {
            op: 'not_within_last';
            days: number;
        } | {
            op: 'on_or_after';
            date: string;
        } | {
            op: 'before';
            date: string;
        };
    } | {
        field: 'customer_since';
        filter: {
            op: 'within_last';
            days: number;
        } | {
            op: 'not_within_last';
            days: number;
        } | {
            op: 'on_or_after';
            date: string;
        } | {
            op: 'before';
            date: string;
        };
    } | {
        field: 'city';
        op: 'in' | 'not_in';
        ids: Array<string>;
    } | {
        field: 'zone';
        op: 'in' | 'not_in';
        ids: Array<string>;
    } | {
        field: 'tags';
        op: 'has_any' | 'has_all' | 'has_none';
        tags: Array<string>;
    } | {
        field: 'marketing_consent';
        channel: 'email' | 'sms' | 'whatsapp' | 'push';
        status: 'subscribed' | 'pending' | 'unsubscribed' | 'not_subscribed';
    } | {
        field: 'customer_type';
        types: Array<'account' | 'guest' | 'merchant'>;
    } | {
        field: 'custom_field';
        definitionId: string;
        op: 'equals' | 'is_set' | 'is_not_set';
        value?: string;
    }>;
};

