export type Market = {
    id: string;
    handle: string;
    name: string;
    /**
     * Only active markets resolve for buyers.
     */
    status: 'draft' | 'active';
    isBackup: boolean;
    revision: number;
    countries: Array<string>;
    /**
     * The root presence of the backup market, or the market's subfolder; null when it has none.
     */
    presence: {
        /**
         * The subfolder (`en-in`: the language and the country), or `''` for the root URL, which only the backup market holds.
         */
        value: string;
        /**
         * The language of the presence's pages (ISO 639-1).
         */
        locale: string;
    } | null;
    /**
     * The currency it sells in: its own, else the shop currency. The backup market always sells in the shop currency.
     */
    currencyCode: string;
    /**
     * The shop currency: the store's books.
     */
    shopCurrencyCode: string;
    /**
     * True when it sells in its own currency: its prices are your product prices converted at its exchange rate, unless a price list fixes them.
     */
    ownCurrency: boolean;
    /**
     * The price increment its prices use, in minor units: the backup market's own, inherited by every market in the shop currency; a market in its own currency uses that currency's (whole taka for BDT, else the minor unit).
     */
    priceIncrementMinor: number;
    priceIncrementInherited: boolean;
    /**
     * Whether the market's prices include tax: checkout adds tax on top when false, and shows it as included when true.
     */
    pricesIncludeTax: boolean;
    /**
     * `fixed`: product prices and the market's fixed price lists. `fx`: product prices converted at its exchange rate, adjusted, rounded up and ending as set. The backup market is always `fixed`.
     */
    priceMode: 'fixed' | 'fx';
    /**
     * The manual exchange rate (market currency per shop currency unit); null uses the rate source. A market in the shop currency converts at 1.
     */
    fxRate: string | null;
    /**
     * When the rate was last set: by the merchant, or taken from the exchange rate app.
     */
    fxRateAsOf: string | null;
    /**
     * Who sets the rate: `manual` (the merchant) or an exchange rate app provider (`<plugin id>:<provider id>`), whose rate is refreshed on the scheduled tick.
     */
    fxRateSource: string;
    /**
     * How long a placed order keeps the rate it was quoted (5 to 1,440 minutes).
     */
    fxLockMinutes: number;
    /**
     * Raises (positive) or lowers (negative) FX-derived prices by this percentage.
     */
    priceAdjustmentPercent: number;
    /**
     * FX-derived prices round up to this step (major units, such as 10 for 10 taka); null rounds to the price increment.
     */
    priceRounding: number | null;
    /**
     * What a rounded price ends in within its step (major units: 9 with a step of 10 ends prices in 9); null for none.
     */
    priceEnding: number | null;
    /**
     * A market that took orders cannot be deleted; set it to draft instead.
     */
    hasOrders: boolean;
    createdAt: string;
    updatedAt: string;
};

export type SalesChannel = {
    id: string;
    handle: string;
    /**
     * The English name; the dashboard shows built-in channels in the staff member's language.
     */
    name: string;
    /**
     * `online_store` (the storefront), `catalog_feed` (Google, Meta), `agent` (AI agents: UCP and agent checkout), `pos`, or `app` (a sales-channel app).
     */
    kind: 'online_store' | 'pos' | 'catalog_feed' | 'agent' | 'app';
    /**
     * The app that declares an `app` channel.
     */
    pluginId: string | null;
    /**
     * An inactive channel shows nothing: its feed is empty and its checkout refuses orders. The online store is always active; an app's channel follows the app.
     */
    status: 'active' | 'inactive';
    position: number;
    /**
     * The inventory locations whose on-hand the channel sells. Every channel sells every location until a merchant unlinks one.
     */
    locationIds: Array<string>;
    /**
     * Products published to it (trashed ones left out).
     */
    publishedProducts: number;
};

export type StoreLanguage = {
    /**
     * ISO 639-1 language code.
     */
    locale: string;
    /**
     * Only a published language's market web addresses are served.
     */
    published: boolean;
    /**
     * The default language: the store's own URL (the backup market's root) and the source text.
     */
    isDefault: boolean;
    /**
     * Market web addresses in this language (`en-in`; `''` is the store's own URL).
     */
    presences: Array<string>;
    /**
     * Resources with a translation in this language (any market).
     */
    translatedResources: number;
};

export type CreateStoreLanguage = {
    locale: string;
    /**
     * Publish at once; default false (translate first, then publish).
     */
    published?: boolean;
};

export type UpdateStoreLanguage = {
    published?: boolean;
    /**
     * Make it the default language (the store's own URL); publishes it.
     */
    isDefault?: true;
};

