    kind: 'section' | 'section_skin' | 'skin' | 'product_block';
    /**
     * The app's section type, skin id or component type.
     */
    type: string;
    /**
     * A skin's target: the unit, or section:<store section type>.
     */
    target?: string;
    /**
     * The theme document path of the reference.
     */
    path: string;
