export type GetApiV1ProductsData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * The page's subfolder presence (`en-in`); its market prices the products shown. Omit for the root (the backup market). An inactive or unknown presence answers 404.
         */
        presence?: string;
        /**
         * Category slug or ID filter
         */
        category?: string;
        /**
         * Search query
         */
        search?: string;
        /**
         * Page number; empty past the first 1,000 products (10,000 on a Paid deployment): use `cursor` to go deeper
         */
        page?: number;
        /**
         * Items per page
         */
        limit?: number;
        /**
         * Continue after the last product of the previous page (its pageInfo.endCursor): newest, price-asc and price-desc only, not with `page` beyond 1. Walks a large catalogue without OFFSET; a cursor from another order is rejected with invalid_cursor.
         */
        cursor?: string;
        /**
         * Sort order. Defaults to relevance when `search` is set, otherwise newest. `rating`: the Bayesian review rank, unreviewed products last.
         */
        sort?: 'relevance' | 'newest' | 'price-asc' | 'price-desc' | 'name-asc' | 'name-desc' | 'discount' | 'rating';
        /**
         * Only products whose published-review average is at least this many whole stars (1-4).
         */
        minRating?: number;
        /**
         * Minimum effective buyer-SKU price
         */
        minPrice?: number | null;
        /**
         * Maximum effective buyer-SKU price
         */
        maxPrice?: number | null;
        /**
         * Free delivery filter
         */
        freeDelivery?: 'true' | 'false';
        /**
         * Discount filter
         */
        hasDiscount?: 'true' | 'false';
        /**
         * Only products a buyer can buy now (exclude sold out)
         */
        inStock?: 'true';
        /**
         * Comma-separated product IDs
         */
        ids?: string;
    };
    url: '/api/v1/products';
};

