export type GetApiV1ProductsResponses = {
    /**
     * Product list with pagination
     */
    200: {
        success: true;
        data: {
            products: Array<{
                id: string;
                name: string;
                productCondition: 'new' | 'refurbished' | 'used' | null;
                price: number;
                slug: string;
                discountType: string | null;
                discountPercentage: number | null;
                discountAmount: number | null;
                freeDelivery: boolean;
                categoryId: string | null;
                hasVariants: boolean;
                availableForSale: boolean;
                quickAddEligible: boolean;
                imageUrl: string | null;
                imageMediaId: string | null;
                imageAlt: string | null;
                /**
                 * The next photo in gallery order, for a card's hover swap. Never a video.
                 */
                secondaryImageUrl: string | null;
                cardFacts?: ProductCardFacts;
                /**
                 * Requested storefront-visible card fields, keyed by namespace.key.
                 */
                fields?: {
                    [key: string]: unknown;
                };
                category: {
                    id: string;
                    name: string;
                    slug: string;
                } | null;
                createdAt: string | null;
                discountedPrice: number;
                priceVaries: boolean;
                /**
                 * Published-review rating; null when the product has no published review.
                 */
                rating: {
                    /**
                     * Average of the published reviews, two decimals truncated (4.66).
                     */
                    average: number;
                    /**
                     * Published reviews.
                     */
                    count: number;
                } | null;
                [key: string]: unknown;
            }>;
            pagination: {
                /**
                 * Page number; 0 for a page read with `cursor`. Numbered pages reach the first 1,000 products (10,000 on a Paid deployment): deeper ones are empty.
                 */
                page: number;
                limit: number;
                /**
                 * Matching products: exact up to the count cap (1,000; 10,000 on a Paid deployment), otherwise the cap with totalIsCapped true.
                 */
                total: number;
                totalPages: number;
                /**
                 * More products match than `total` counts (show "1,000+").
                 */
                totalIsCapped: boolean;
            };
            pageInfo: {
                hasNextPage: boolean;
                /**
                 * Pass as `cursor` for the next page of the newest, price-asc and price-desc orders; null for other orders and for an empty page.
                 */
                endCursor: string | null;
            };
            priceRange: {
                min: number;
                max: number;
            };
            facets: Array<CatalogFacet>;
            /**
             * "N★ & up" rating facet, highest first: empty when no product in scope has a published review, otherwise 4, 3, 2 (plus a selected `minRating`), counts may be 0.
             */
            ratingFacet: Array<{
                /**
                 * Whole stars: products averaging at least this (`minRating`).
                 */
                min: number;
                /**
                 * Products matching the other selections and this threshold.
                 */
                count: number;
            }>;
            /**
             * Set when `search` matched nothing and these products are for the closest catalog words instead (typo or Bangla correction).
             */
            correctedQuery: string | null;
        };
    };
};

